const programa = $json.programa;

const PRECIOS = {
  'Diplomado Avanzado en Asistencia Quirúrgica - Versión online': { amount: 35, currency: 'USD' },
  'Diplomado Avanzado en Asistencia Quirúrgica - Versión semipresencial': { amount: 14400, currency: 'DOP' },
  'Taller de Sutura Online': { amount: 35, currency: 'USD' },
  'Diplomado Avanzado en Interpretación de Neuroimágenes': { amount: 35, currency: 'USD' },
  'Diplomado Avanzado en Instrumentación Laparoscópica': { amount: 35, currency: 'USD' },
  'Diplomado Avanzado en Manejo de Heridas y Ostomías - Versión online': { amount: 35, currency: 'USD' },
  'Diplomado Avanzado en Manejo de Heridas y Ostomías - Versión semipresencial': { amount: 8800, currency: 'DOP' }
};

const precio = PRECIOS[programa];

if (!precio) {
  throw new Error('Programa desconocido, no se pudo calcular el precio: ' + programa);
}

return [{
  json: {
    ...$json,
    monto_pago: precio.amount,
    moneda_pago: precio.currency
  }
}];

